/** The version hello asks for and welcome answers with. */
export const PROTOCOL_VERSION = 1;
/** A turn's id: what `say` names, and every frame of the turn echoes. */
export const TURN_ID_PATTERN = /^[A-Za-z0-9_-]{1,64}$/;
/** A client's id: its identity on the brain is `desktop-<id>`. */
export const CLIENT_ID_PATTERN = /^[a-z0-9][a-z0-9-]{0,31}$/;
/** The longest `say`, in characters (code points), once trimmed. */
export const SAY_MAX_CHARS = 8000;
/** The longest client name, in characters (code points). */
export const CLIENT_NAME_MAX_CHARS = 64;
/** The most widgets one subscribe may name. */
export const WIDGETS_MAX = 8;

/** The codes the server closes a session with. */
export const CLOSE = {
  goneQuiet: 4000,
  badFrame: 4400,
  badToken: 4401,
  noHello: 4408,
  full: 4409,
  unsupported: 4426,
} as const;

export type Cap = "text" | "audio-in" | "audio-out" | "speak-local" | "vrm" | "widgets";
export const CAP_VALUES: readonly Cap[] = ["text", "audio-in", "audio-out", "speak-local", "vrm", "widgets"];
export type TurnState = "listening" | "transcribing" | "thinking" | "speaking" | "idle";
export const TURN_STATE_VALUES: readonly TurnState[] = ["listening", "transcribing", "thinking", "speaking", "idle"];
export type ErrorCode = "busy" | "bad_frame" | "turn_failed" | "stt_failed" | "not_allowed" | "internal";
export const ERROR_CODE_VALUES: readonly ErrorCode[] = ["busy", "bad_frame", "turn_failed", "stt_failed", "not_allowed", "internal"];
export type MoodName = "dry" | "pleased" | "alarmed" | "weary";
export const MOOD_NAME_VALUES: readonly MoodName[] = ["dry", "pleased", "alarmed", "weary"];

// ── Client to server ────────────────────────────────────────────────────────

export interface ClientInfo {
  id: string;
  name: string;
  caps: Cap[];
}

export interface Hello {
  type: "hello";
  protocol?: number;
  token: string;
  client: ClientInfo;
}

export interface Say {
  type: "say";
  turn_id: string;
  text: string;
}

/**
 * Follows one or more binary frames of audio (Phase 2).
 */
export interface AudioEnd {
  type: "audio_end";
  turn_id: string;
  sample_rate?: number;
  channels?: number;
  format?: "pcm16";
}

export interface Cancel {
  type: "cancel";
  turn_id: string;
}

/**
 * The widgets the client wants fed, replacing any it asked for before;
 * none stops the feed. A name the server doesn't feed is let be.
 */
export interface Subscribe {
  type: "subscribe";
  widgets: string[];
}

// ── Server to client ────────────────────────────────────────────────────────

export interface Welcome {
  type: "welcome";
  protocol: number;
  identity: string;
  display_name: string;
  server_caps: Cap[];
  thread_id: string;
}

export interface State {
  type: "state";
  turn_id: string;
  state: TurnState;
}

/**
 * Phase 2: what was heard.
 */
export interface Stt {
  type: "stt";
  turn_id: string;
  text: string;
}

export interface Token {
  type: "token";
  turn_id: string;
  delta: string;
  restart: boolean;
}

/**
 * His mood for the reply that follows, from the tag the model began it
 * with (taken off the tokens, the speech and done's text). Sent before the
 * first token of the part of the reply it heads; a reply in several parts
 * (the model wrote, called a tool, wrote again) may name one per part, and
 * the newest stands; a part that is only a tag tells its mood as the next
 * part begins. Always before the turn's done or error. A reply that names
 * none sends none.
 */
export interface MoodFrame {
  type: "mood";
  turn_id: string;
  mood: MoodName;
}

export interface Progress {
  type: "progress";
  turn_id: string;
  text: string;
}

/**
 * Phase 2, brain-side TTS: one sentence of audio.
 */
export interface Speech {
  type: "speech";
  turn_id: string;
  seq: number;
  mime: "audio/wav";
  b64: string;
  final: boolean;
}

/**
 * Phase 2, body-side TTS: one sentence for the client to synthesise.
 */
export interface Speak {
  type: "speak";
  turn_id: string;
  seq: number;
  text: string;
  final: boolean;
}

/**
 * A turn's end. `text` is the whole reply, which supersedes the tokens.
 *
 * `images` are data: URLs (data:image/png;base64,...), so the client needs
 * nothing but this socket to show them, on this machine or another.
 */
export interface Done {
  type: "done";
  turn_id: string;
  text: string;
  images: string[];
  interrupted: boolean;
}

/**
 * `text` is Fritz's own words, fit to show; never a raw exception.
 */
export interface ErrorFrame {
  type: "error";
  turn_id: string | null;
  code: ErrorCode;
  text: string;
}

/**
 * One widget's news: `payload` is its payload model's (WidgetPayloads
 * in TypeScript), as an object. It holds for `ttl_s` more seconds (0:
 * until the next), so a desk can tell a stale one.
 */
export interface Widget {
  type: "widget";
  name: string;
  payload: Record<string, unknown>;
  ttl_s: number;
}

/**
 * Phase 3.
 */
export interface Reminder {
  type: "reminder";
  schedule_id: number;
  text: string;
}

// ── Both ways: either side pings, and the other answers ─────────────────────

/**
 * Either side; the other answers with a Pong carrying the same t.
 */
export interface Ping {
  type: "ping";
  t: number;
}

export interface Pong {
  type: "pong";
  t: number;
}

// ── Widget payloads ─────────────────────────────────────────────────────────

/**
 * The brain's time: `now` in ISO 8601 with its zone's offset, and the
 * zone's IANA name (SCHEDULE_TIMEZONE). The desk ticks the seconds itself.
 */
export interface ClockPayload {
  now: string;
  zone: string;
}

/**
 * Now and today at the brain's WEATHER_LATITUDE and WEATHER_LONGITUDE,
 * from Open-Meteo. `code` is the WMO weather code and `summary` its words;
 * `observed_at` is Open-Meteo's time for `now`, ISO 8601 with the place's
 * offset.
 */
export interface WeatherPayload {
  temperature: number;
  feels_like: number;
  high: number;
  low: number;
  unit: "F" | "C";
  code: number;
  summary: string;
  wind: number;
  wind_unit: "mph" | "km/h";
  is_day: boolean;
  observed_at: string;
}

/**
 * One question and its answer, each cut to its first few hundred
 * characters, his mood for it, and when it ended (ISO 8601, UTC).
 */
export interface DeskExchange {
  asked: string;
  answered: string;
  mood: MoodName | null;
  at: string;
}

/**
 * His desk: the last exchange at a desk of this identity since the
 * brain started, or none yet.
 */
export interface DeskPayload {
  last: DeskExchange | null;
}

/** Each widget's payload, by its name (a Widget frame's `name`). */
export interface WidgetPayloads {
  clock: ClockPayload;
  weather: WeatherPayload;
  desk: DeskPayload;
}
/** Every widget the server may feed. */
export const WIDGET_NAMES = [
  "clock",
  "weather",
  "desk",
] as const satisfies readonly (keyof WidgetPayloads)[];

export type ClientFrame = Hello | Say | AudioEnd | Cancel | Subscribe | Ping | Pong;
export type ServerFrame = Welcome | State | Stt | Token | MoodFrame | Progress | Speech | Speak | Done | ErrorFrame | Widget | Reminder | Ping | Pong;

/** Every `type` the server sends. */
export const SERVER_FRAME_TYPES = [
  "welcome",
  "state",
  "stt",
  "token",
  "mood",
  "progress",
  "speech",
  "speak",
  "done",
  "error",
  "widget",
  "reminder",
  "ping",
  "pong",
] as const satisfies readonly ServerFrame["type"][];

// ── The check ────────────────────────────────────────────────────────────

type Check = (v: unknown) => boolean;
const isObj = (v: unknown): v is Record<string, unknown> =>
  typeof v === "object" && v !== null && !Array.isArray(v);
const str: Check = (v) => typeof v === "string";
const int: Check = (v) => Number.isInteger(v);
const bool: Check = (v) => typeof v === "boolean";
const num: Check = (v) => typeof v === "number" && Number.isFinite(v);
const oneOf = (values: readonly unknown[]): Check => (v) => values.includes(v);
const listOf = (item: Check): Check => (v) => Array.isArray(v) && v.every((e) => item(e));
const orNull = (inner: Check): Check => (v) => v === null || inner(v);
const shape = (fields: Readonly<Record<string, Check>>): Check => (v) =>
  isObj(v) && Object.entries(fields).every(([k, check]) => check(v[k]));

/** Each server frame's fields, by its `type`. A Map, so no `type` reaches
 * Object.prototype (`constructor`, `__proto__`). */
const SERVER_CHECKS: ReadonlyMap<string, Check> = new Map<string, Check>([
  ["welcome", shape({ type: oneOf(["welcome"]), protocol: int, identity: str, display_name: str, server_caps: listOf(oneOf(CAP_VALUES)), thread_id: str })],
  ["state", shape({ type: oneOf(["state"]), turn_id: str, state: oneOf(TURN_STATE_VALUES) })],
  ["stt", shape({ type: oneOf(["stt"]), turn_id: str, text: str })],
  ["token", shape({ type: oneOf(["token"]), turn_id: str, delta: str, restart: bool })],
  ["mood", shape({ type: oneOf(["mood"]), turn_id: str, mood: oneOf(MOOD_NAME_VALUES) })],
  ["progress", shape({ type: oneOf(["progress"]), turn_id: str, text: str })],
  ["speech", shape({ type: oneOf(["speech"]), turn_id: str, seq: int, mime: oneOf(["audio/wav"]), b64: str, final: bool })],
  ["speak", shape({ type: oneOf(["speak"]), turn_id: str, seq: int, text: str, final: bool })],
  ["done", shape({ type: oneOf(["done"]), turn_id: str, text: str, images: listOf(str), interrupted: bool })],
  ["error", shape({ type: oneOf(["error"]), turn_id: orNull(str), code: oneOf(ERROR_CODE_VALUES), text: str })],
  ["widget", shape({ type: oneOf(["widget"]), name: str, payload: isObj, ttl_s: int })],
  ["reminder", shape({ type: oneOf(["reminder"]), schedule_id: int, text: str })],
  ["ping", shape({ type: oneOf(["ping"]), t: int })],
  ["pong", shape({ type: oneOf(["pong"]), t: int })],
]);

/** Whether `x` is a frame the server sends: an object whose `type` is one
 * of SERVER_FRAME_TYPES, with every field of that frame there, of its type.
 * Fields it doesn't know are allowed: a newer server may add some. */
export function isServerFrame(x: unknown): x is ServerFrame {
  if (!isObj(x) || typeof x.type !== "string") return false;
  const check = SERVER_CHECKS.get(x.type);
  return check !== undefined && check(x);
}

/** Each widget's payload's fields, by the widget's name. */
const PAYLOAD_CHECKS: ReadonlyMap<string, Check> = new Map<string, Check>([
  ["clock", shape({ now: str, zone: str })],
  ["weather", shape({ temperature: num, feels_like: num, high: num, low: num, unit: oneOf(["F", "C"]), code: int, summary: str, wind: num, wind_unit: oneOf(["mph", "km/h"]), is_day: bool, observed_at: str })],
  ["desk", shape({ last: orNull(shape({ asked: str, answered: str, mood: orNull(oneOf(MOOD_NAME_VALUES)), at: str })) })],
]);

/** Whether `payload` is widget `name`'s, every field there, of its type.
 * Fields it doesn't know are allowed, as in a frame. */
export function isWidgetPayload<K extends keyof WidgetPayloads>(name: K, payload: unknown): payload is WidgetPayloads[K] {
  const check = PAYLOAD_CHECKS.get(name);
  return check !== undefined && check(payload);
}
